recommendation:
Implement a two-step admin transfer pattern: store a pendingAdmin address first, then require the new admin to call acceptAdmin() to confirm. Example:

address public pendingAdmin;
function proposeAdmin(address _user) external onlyAdmin {
    require(_user != address(0));
    pendingAdmin = _user;
}
function acceptAdmin() external {
    require(msg.sender == pendingAdmin);
    s2Admin = pendingAdmin;
    pendingAdmin = address(0);
    emit AdminUpdated(s2Admin);
}

Add a combined fee cap check. After each fee update, verify the combined total does not exceed a reasonable maximum (e.g., 20%):

function setBuyerFee(uint256 _amount) external onlyAdmin {
    require(_amount <= 5000, 'Buyer fee cannot exceed 50%');
    require(_amount + sellerFee <= 2000, 'Combined fees cannot exceed 20%');
    buyerFee = _amount;
    emit DefaultBuyerFeeUpdated(_amount);
}

